INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Lampu Otomatis yang Tidak Tahu Kapan Gelap$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak proyek butuh tahu terang atau gelap: lampu taman yang menyala sendiri saat malam, tirai yang menutup saat siang terik, atau alarm yang aktif saat lampu ruangan dimatikan. Tanpa sensor cahaya, Arduino buta terhadap kondisi sekitar. Sensor LDR (Light Dependent Resistor) adalah solusi termurah — komponen seharga ribuan rupiah yang resistansinya berubah mengikuti intensitas cahaya.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Cara Kerja LDR$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$LDR adalah resistor yang nilai resistansinya turun saat cahaya terang dan naik saat gelap — bisa dari ratusan ohm di siang hari hingga megaohm di kegelapan. Karena Arduino tidak bisa membaca resistansi langsung, LDR dirangkai sebagai pembagi tegangan dengan resistor tetap 10k ohm, lalu tegangan tengahnya dibaca pin analog A0 lewat analogRead() yang menghasilkan nilai 0 sampai 1023: makin terang, makin besar nilainya.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Arduino Uno (atau Nano/ESP32)$txt$, $txt$Sensor LDR (fotoresistor)$txt$, $txt$Resistor 10k ohm$txt$, $txt$Breadboard dan kabel jumper$txt$, $txt$LED dan resistor 220 ohm (untuk uji lampu otomatis)$txt$, $txt$Kabel USB dan komputer dengan Arduino IDE$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$1) Rangkaian pembagi tegangan: hubungkan satu kaki LDR ke 5V, kaki satunya ke A0 sekaligus ke resistor 10k yang ujungnya ke GND. 2) Baca nilai: unggah program analogRead(A0) dan tampilkan ke Serial Monitor — tutup LDR dengan tangan dan lihat nilainya turun, arahkan ke lampu dan lihat nilainya naik. 3) Tentukan ambang: catat nilai saat ruangan terang dan saat gelap, pilih angka tengah sebagai batas (misalnya 500). 4) Lampu otomatis: hubungkan LED ke pin 13; program: jika nilai di bawah ambang maka digitalWrite(13, HIGH), jika di atas maka LOW — lampu menyala saat gelap dan mati saat terang.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Nilai tidak berubah: LDR terbalik tidak masalah (tidak berkutub), yang salah biasanya wiring pembagi tegangan — cek sambungan ke 5V, A0, dan GND$txt$, $txt$Nilai berfluktuasi liar: cahaya ruangan berkedip atau kabel longgar — rapatkan jumper dan jauhi lampu neon yang berkedip$txt$, $txt$Ambang tidak cocok: tiap ruangan berbeda — kalibrasi ulang ambang di lokasi sebenarnya, bukan di meja kerja$txt$, $txt$LED tidak menyala: resistor LED terlalu besar atau kaki terbalik — kaki panjang LED ke pin 13$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Proyek berhasil jika Serial Monitor menunjukkan nilai berubah jelas antara terang dan gelap, dan LED menyala otomatis saat LDR ditutup tangan. Langkah berikutnya: gabungkan dengan RTC agar lampu hanya aktif di jam malam, buat pengukur intensitas cahaya dengan tampilan LCD, atau kendalikan relay untuk lampu AC 220V (hati-hati dengan tegangan tinggi).$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-ELEKTRONIK16-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Jengkol Keras dan Bau Menyengat$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Rendang jengkol adalah favorit banyak orang, tetapi sering gagal: jengkol keras seperti karet, bau menyengat memenuhi rumah, atau bumbu tidak meresap ke dalam. Padahal jengkol yang dimasak benar itu empuk, gurih, dan bumbunya meresap sampai ke tengah — bahkan yang tadinya tidak suka bisa berubah pikiran.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Kunci Jengkol Empuk$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kunci utama ada dua: pilih jengkol tua (kulit cokelat gelap, daging kuning kecokelatan — lebih empuk dan pulen) dan rebus dua kali. Rebusan pertama dengan air cucian beras atau daun salam membuang bau dan getah; rebusan kedua hingga empuk sebelum dimasak dengan bumbu. Jengkol yang langsung dimasak mentah hampir pasti keras dan bau.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan-bahan (4-5 porsi)$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$500 gram jengkol tua, kupas dan belah dua$txt$, $txt$400 ml santan kental dari 1 butir kelapa$txt$, $txt$2 lembar daun salam, 3 lembar daun jeruk, 1 batang serai memarkan, 2 cm lengkuas$txt$, $txt$Bumbu halus: 8 bawang merah, 5 bawang putih, 8 cabai merah keriting, 3 cabai rawit, 3 kemiri sangrai, 2 cm kunyit, 2 cm jahe, 1 sdt ketumbar sangrai$txt$, $txt$Garam, gula merah, dan kaldu secukupnya$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Memasak$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$1) Rebus jengkol dengan air cucian beras dan daun salam 20 menit, buang airnya. 2) Rebus lagi dengan air bersih hingga empuk (30-40 menit), tiriskan lalu pipihkan sedikit dengan ulekan agar bumbu meresap. 3) Tumis bumbu halus dengan serai, lengkuas, daun salam, dan daun jeruk hingga harum dan berminyak. 4) Masukkan jengkol, aduk rata, tuang santan. 5) Masak dengan api kecil sambil sesekali diaduk hingga santan menyusut dan bumbu mengering menempel — sekitar 45-60 menit. Bumbui garam, gula merah, dan kaldu.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Jengkol keras: memakai jengkol muda atau melewatkan rebusan dua kali — selalu pilih yang tua dan rebus hingga empuk dulu$txt$, $txt$Bau menyengat: air rebusan pertama tidak dibuang — buang dan ganti air bersih$txt$, $txt$Santan pecah: api terlalu besar — masak selalu dengan api kecil dan aduk berkala$txt$, $txt$Bumbu tidak meresap: jengkol tidak dipipihkan — geprek ringan sebelum dimasak agar bumbu masuk$txt$]) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Penyajian$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Rendang jengkol berhasil jika jengkol empuk saat ditekan sendok, bumbu kering menempel, dan rasanya gurih pedas manis seimbang. Sajikan dengan nasi hangat dan kerupuk. Simpan di wadah tertutup di kulkas hingga 4 hari — rasanya justru makin meresap keesokan harinya.$txt$) FROM madevi.articles v WHERE v.business_code = 'TUT-MASAK21-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Logam yang Lunak Seperti Mentega$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Natrium adalah logam yang sangat lunak — bisa dipotong dengan pisau dapur — berwarna keperakan dan berkilau saat baru dipotong, tetapi cepat kusam di udara. Ia anggota golongan 1A (logam alkali) dengan simbol Na dari bahasa Latin natrium, dan merupakan unsur keenam paling melimpah di kerak bumi.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Sangat Reaktif: Jangan Sentuh Air$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Natrium hanya punya satu elektron valensi yang mudah dilepas, sehingga ia bereaksi hebat dengan air menghasilkan gas hidrogen dan panas yang bisa menyulut api. Karena itu natrium murni disimpan dalam minyak tanah, bukan di udara terbuka. Reaksi ini adalah alasan natrium tidak pernah ditemukan bebas di alam.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Natrium dalam Kehidupan Sehari-hari$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Garam dapur (NaCl): senyawa natrium paling terkenal, dipakai setiap hari$txt$, $txt$Sabun dan detergen: natrium hidroksida (NaOH) bahan pembuat sabun$txt$, $txt$Lampu jalan sodium: cahaya kuning khas dari uap natrium yang sangat efisien$txt$, $txt$Soda kue: natrium bikarbonat untuk pengembang kue dan pereda maag$txt$, $txt$Aki dan baterai: senyawa natrium dipakai dalam berbagai baterai$txt$]) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Peran dalam Tubuh Manusia$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Ion natrium (Na+) sangat penting bagi tubuh: menjaga keseimbangan cairan, membantu kerja saraf mengirim sinyal listrik, dan mendukung kontraksi otot. Kekurangan natrium bisa menyebabkan kram dan lemas, tetapi kelebihan — terutama dari garam berlebih — menaikkan tekanan darah. Anjuran umum: batasi garam dapur sekitar satu sendok teh per hari.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Penemuan dan Produksi$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Natrium pertama kali diisolasi oleh Humphry Davy pada tahun 1807 lewat elektrolisis — teknik yang saat itu baru ditemukan. Kini natrium diproduksi dengan elektrolisis lelehan garam dapur (proses Downs), dan sebagian besar langsung diubah menjadi senyawa bermanfaat seperti NaOH dan NaCl, bukan dipakai sebagai logam murni.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-KIMIA26-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Konfrontasi?$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Konfrontasi adalah kebijakan politik Indonesia pada 1963-1966 yang menentang pembentukan Federasi Malaysia. Presiden Soekarno menyebut Malaysia sebagai proyek neokolonialisme Inggris dan mencanangkan semboyan Ganyang Malaysia. Meski disebut konfrontasi, konflik ini sebagian besar berupa perang terbatas dan diplomasi, bukan perang terbuka skala penuh.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang: Lahirnya Malaysia$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Inggris berencana menggabungkan Malaya, Singapura, Sabah, dan Sarawak menjadi Federasi Malaysia pada 1963. Indonesia menolak karena menilai penggabungan itu dirancang Inggris untuk mempertahankan pengaruhnya, dan karena klaim historis atas wilayah Kalimantan Utara. Brunei yang semula direncanakan ikut akhirnya membatalkan diri setelah pemberontakan 1962.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Jalannya Konfrontasi$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$1963: Indonesia memutuskan hubungan diplomatik dan memulai infiltrasi sukarelawan ke perbatasan Kalimantan$txt$, $txt$1964: konfrontasi memanas — infiltrasi ke Semenanjung Malaya, Inggris mengerahkan pasukan Persemakmuran$txt$, $txt$Pertempuran di Kalimantan: patroli dan penyergapan di sepanjang perbatasan, kedua pihak menahan diri dari perang total$txt$, $txt$1965: fokus Indonesia terpecah oleh krisis dalam negeri pasca peristiwa 30 September$txt$, $txt$1966: pemerintahan baru membuka jalan perdamaian$txt$]) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Akhir: Perjanjian Bangkok 1966$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Pada 11 Agustus 1966 Indonesia dan Malaysia menandatangani Perjanjian Bangkok yang mengakhiri konfrontasi. Indonesia mengakui Malaysia, hubungan diplomatik dipulihkan, dan kedua negara sepakat bekerja sama. Perdamaian ini menjadi fondasi lahirnya ASEAN setahun kemudian, pada 1967.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Warisan bagi Indonesia$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Konfrontasi meninggalkan pelajaran penting: sengketa antarnegara tetangga lebih baik diselesaikan lewat diplomasi dan kerja sama kawasan. Semangat inilah yang mendorong Indonesia menjadi pendiri ASEAN — organisasi yang hingga kini menjaga stabilitas Asia Tenggara lewat dialog, bukan senjata.$txt$) FROM madevi.articles v WHERE v.business_code = 'EXP-SEJARAH22-001';
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu membedakan besaran pokok dan besaran turunan, menyebutkan tujuh besaran pokok beserta satuan SI-nya, menentukan dimensi suatu besaran, serta menerapkan aturan angka penting dalam perhitungan.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Besaran Pokok dan Satuan SI$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Besaran pokok adalah besaran yang ditetapkan sebagai dasar dan tidak diturunkan dari besaran lain. Ada tujuh: panjang (meter, m), massa (kilogram, kg), waktu (sekon, s), suhu (kelvin, K), kuat arus (ampere, A), jumlah zat (mol), dan intensitas cahaya (kandela, cd). Semua satuan fisika modern mengacu pada sistem internasional (SI) ini.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Besaran Turunan$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Kecepatan: meter per sekon (m/s) — diturunkan dari panjang dan waktu$txt$, $txt$Gaya: newton (N) = kg m/s2 — diturunkan dari massa, panjang, waktu$txt$, $txt$Energi: joule (J) = kg m2/s2$txt$, $txt$Daya: watt (W) = joule per sekon$txt$, $txt$Tekanan: pascal (Pa) = newton per meter persegi$txt$]) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Dimensi Besaran$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Dimensi menyatakan cara suatu besaran tersusun dari besaran pokok, ditulis dengan huruf: [M] massa, [L] panjang, [T] waktu. Contoh: kecepatan berdimensi [L][T]^-1, gaya berdimensi [M][L][T]^-2. Dimensi berguna untuk memeriksa kebenaran rumus — kedua ruas persamaan harus berdimensi sama.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Contoh Soal Terpecahkan$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Tentukan dimensi energi kinetik Ek = 1/2 m v^2. Jawab: massa berdimensi [M], kecepatan [L][T]^-1 sehingga v^2 berdimensi [L]^2[T]^-2. Maka Ek berdimensi [M][L]^2[T]^-2 — sama dengan dimensi joule. Jadi rumusnya konsisten secara dimensi.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan Kunci Jawaban$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Soal 1: Sebutkan 7 besaran pokok dan satuannya. Kunci: panjang-m, massa-kg, waktu-s, suhu-K, arus-A, jumlah zat-mol, intensitas cahaya-cd$txt$, $txt$Soal 2: Tentukan dimensi daya. Kunci: [M][L]^2[T]^-3$txt$, $txt$Soal 3: 2,50 cm + 1,2 cm = ? (aturan angka penting). Kunci: 3,7 cm (mengikuti desimal paling sedikit)$txt$]) FROM madevi.articles v WHERE v.business_code = 'SCH-SMA-FIS6-001';
