INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar materi ini, kamu bisa menjelaskan apa itu keliling bangun datar dan menghitung keliling persegi, persegi panjang, dan segitiga dengan benar. Keliling berguna dalam kehidupan sehari-hari, misalnya menghitung pagar yang dibutuhkan mengelilingi kebun.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Keliling?$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Keliling adalah panjang seluruh sisi yang mengelilingi sebuah bangun datar. Bayangkan kamu berjalan mengelilingi lapangan dari titik awal sampai kembali lagi ke titik awal — jarak yang kamu tempuh itulah keliling. Jadi cara menghitung keliling sangat mudah: jumlahkan semua panjang sisinya.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 4, jsonb_build_object('text', $txt$Keliling Persegi$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Persegi punya 4 sisi yang sama panjang. Jika satu sisinya s, maka keliling = 4 x s. Contoh: persegi dengan sisi 7 cm, kelilingnya = 4 x 7 = 28 cm. Mudah, kan?$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 6, jsonb_build_object('text', $txt$Keliling Persegi Panjang$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Persegi panjang punya panjang p dan lebar l. Keliling = 2 x (p + l). Contoh: panjang 10 cm dan lebar 6 cm, kelilingnya = 2 x (10 + 6) = 2 x 16 = 32 cm. Jangan lupa jumlahkan dulu panjang dan lebarnya, baru dikali 2.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'HEADING', 8, jsonb_build_object('text', $txt$Keliling Segitiga$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Segitiga punya 3 sisi: a, b, dan c. Keliling = a + b + c, tinggal jumlahkan ketiganya. Contoh: sisi-sisinya 5 cm, 7 cm, dan 9 cm, maka kelilingnya = 5 + 7 + 9 = 21 cm.$txt$) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
