INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) SELECT gen_random_uuid(), v.id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Soal 1: Keliling persegi dengan sisi 9 cm? Kunci: 4 x 9 = 36 cm$txt$, $txt$Soal 2: Persegi panjang p=12 cm, l=5 cm. Kelilingnya? Kunci: 2 x (12+5) = 34 cm$txt$, $txt$Soal 3: Segitiga dengan sisi 6 cm, 8 cm, 10 cm. Kelilingnya? Kunci: 6+8+10 = 24 cm$txt$]) FROM madevi.articles v WHERE v.business_code = 'SCH-SD-MAT20-001';
